import sys
from collections import defaultdict

def count_bits(x):
    return bin(x).count('1')

def main():
    input = sys.stdin.read().split()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        Q = int(input[index])
        index += 1
        S = set()
        even_count = 0
        odd_count = 0
        for _ in range(Q):
            X = int(input[index])
            index += 1
            if X not in S:
                S.add(X)
                bit_count_X = count_bits(X)
                if bit_count_X % 2 == 0:
                    even_count += 1
                else:
                    odd_count += 1
                new_elements = set()
                for y in S:
                    if y != X:
                        new_element = y ^ X
                        if new_element not in S:
                            new_elements.add(new_element)
                for z in new_elements:
                    S.add(z)
                    bit_count_Z = count_bits(z)
                    if bit_count_Z % 2 == 0:
                        even_count += 1
                    else:
                        odd_count += 1
            results.append(f"{even_count} {odd_count}")
    print("\n".join(results))

main()
